def compute(vars):
    net_income = vars["Net Income"]
    revenue = vars["Revenue"]
    multiplier = vars["100"]

    if revenue == 0:
        return None

    ratio = net_income / revenue
    net_profit_margin = ratio * multiplier

    return {
        "value": net_profit_margin,
        "trace": {
            "Net Income": net_income,
            "Revenue": revenue,
            "100": multiplier,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
